// src/routes/Routes.jsx
import React from "react";
import { Route, Switch } from "react-router-dom";

import Home from "../pages/Home";
import Catalog from "../pages/Catalog";
import Detail from "../pages/detail/Detail";
import SignIn from "../pages/SignIn";
import Register from "../pages/Register";
import Preferences from "../pages/Preferences";
// Change the import
import Watchlist from "../pages/Watchlist"; // instead of Favorites

// Inside <Switch>, change the route:
<Route path={`/${Config.HOME_PAGE}/watchlist`} exact component={Watchlist} />
import * as Config from "../constants/Config";

const Routes = () => {
  return (
    <Switch>
      <Route path="/signin" component={SignIn} />
      <Route path="/register" component={Register} />
      <Route path="/preferences" component={Preferences} />

      {/* Favorites Page */}
      <Route
        path={`/${Config.HOME_PAGE}/favorites`}
        exact
        component={Favorites}
      />

      {/* 1. Base Genre Page (Shows genre dropdown) */}
      <Route
        path={`/${Config.HOME_PAGE}/:category/genre`}
        exact
        render={(props) => <Catalog {...props} isGenre={true} />}
      />

      {/* 2. Specific Genre Route */}
      <Route
        path={`/${Config.HOME_PAGE}/:category/genre/:genreName`}
        render={(props) => <Catalog {...props} isGenre={true} />}
      />

      {/* 3. Search Route */}
      <Route
        path={`/${Config.HOME_PAGE}/:category/search/:keyword`}
        component={Catalog}
      />

      {/* 4. Detail Route */}
      <Route
        path={`/${Config.HOME_PAGE}/:category/:id`}
        component={Detail}
      />

      {/* 5. General Catalog Route */}
      <Route
        path={`/${Config.HOME_PAGE}/:category`}
        component={Catalog}
      />

      {/* 6. Home Route */}
      <Route
        path={`/${Config.HOME_PAGE}`}
        exact
        component={Home}
      />
    </Switch>
  );
};

export default Routes;
